function(container, apiUrl, tables) {
  let orderItems = [];
  let allProducts = [];
  let allStores = [];
  let demandPredictions = [];
  let salesHistory = [];

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 店舗マスタの読み込み
      const stores = await window.aivicApi.list(1);
      if (stores) {
        allStores = stores;
        const storeSelect = container.querySelector('#store-select');
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join('');
      }

      // 商品マスタの読み込み
      const products = await window.aivicApi.list(2);
      if (products) {
        allProducts = products;
      }

      // 需要予測結果の読み込み
      const predictions = await window.aivicApi.list(8);
      if (predictions) {
        demandPredictions = predictions;
      }

      // 売上実績データの読み込み
      const sales = await window.aivicApi.list(3);
      if (sales) {
        salesHistory = sales;
      }
    } catch (error) {
      console.error('初期データの読み込みに失敗しました:', error);
    }
  }

  // 商品一覧の描画
  function renderProductList(products) {
    const tbody = container.querySelector('#product-list');
    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center; padding: 2rem;">該当する商品が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.id);
      const predictedQuantity = prediction ? prediction.予測数量 : 0;

      return `
        <tr data-id="${product.id}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.id}" /></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>${predictedQuantity}</td>
          <td><input type="number" class="input manual-quantity" data-product-id="${product.id}" min="0" value="${predictedQuantity}" style="width: 80px;" /></td>
          <td><button class="action-btn secondary prediction-detail-btn" data-product-id="${product.id}">詳細</button></td>
          <td><button class="action-btn add-to-order-btn" data-product-id="${product.id}">追加</button></td>
        </tr>
      `;
    }).join('');
  }

  // 発注一覧の描画
  function renderOrderList() {
    const tbody = container.querySelector('#order-list');
    if (orderItems.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" class="muted" style="text-align: center; padding: 2rem;">発注商品がありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orderItems.map(item => `
      <tr data-id="${item.id}">
        <td>${item.商品コード}</td>
        <td>${item.商品名}</td>
        <td>¥${item.単価.toLocaleString()}</td>
        <td><input type="number" class="input order-quantity" data-item-id="${item.id}" min="1" value="${item.数量}" style="width: 80px;" /></td>
        <td>¥${(item.単価 * item.数量).toLocaleString()}</td>
        <td><button class="action-btn secondary remove-item-btn" data-item-id="${item.id}">削除</button></td>
      </tr>
    `).join('');

    updateTotalAmount();
  }

  // 発注総額の更新
  function updateTotalAmount() {
    const total = orderItems.reduce((sum, item) => sum + (item.単価 * item.数量), 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 商品検索
  container.querySelector('#btn-search-products').addEventListener('click', () => {
    const category = container.querySelector('#category-select').value;
    const searchText = container.querySelector('#product-search').value.toLowerCase();

    let filteredProducts = allProducts.filter(product => product.有効フラグ);

    if (category) {
      filteredProducts = filteredProducts.filter(product => 
        product.商品カテゴリID && product.商品カテゴリID.includes(category)
      );
    }

    if (searchText) {
      filteredProducts = filteredProducts.filter(product => 
        (product.商品名 && product.商品名.toLowerCase().includes(searchText)) ||
        (product.商品コード && product.商品コード.toLowerCase().includes(searchText))
      );
    }

    renderProductList(filteredProducts);
  });

  // 発注商品への追加
  container.addEventListener('click', (e) => {
    const addBtn = e.target.closest('.add-to-order-btn');
    if (addBtn) {
      const productId = addBtn.dataset.productId;
      const product = allProducts.find(p => p.id === productId);
      const quantityInput = container.querySelector(`.manual-quantity[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 1;

      if (quantity <= 0) {
        alert('発注数量は1以上で入力してください');
        return;
      }

      // 既に追加済みかチェック
      const existingIndex = orderItems.findIndex(item => item.id === productId);
      if (existingIndex >= 0) {
        orderItems[existingIndex].数量 = quantity;
      } else {
        orderItems.push({
          id: productId,
          商品コード: product.商品コード,
          商品名: product.商品名,
          単価: product.単価,
          数量: quantity
        });
      }

      renderOrderList();
    }

    // 発注商品の削除
    const removeBtn = e.target.closest('.remove-item-btn');
    if (removeBtn) {
      const itemId = removeBtn.dataset.itemId;
      orderItems = orderItems.filter(item => item.id !== itemId);
      renderOrderList();
    }

    // 予測根拠詳細表示
    const predictionBtn = e.target.closest('.prediction-detail-btn');
    if (predictionBtn) {
      const productId = predictionBtn.dataset.productId;
      showPredictionDetails(productId);
    }
  });

  // 発注数量の変更
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('order-quantity')) {
      const itemId = e.target.dataset.itemId;
      const quantity = parseInt(e.target.value) || 1;

      if (quantity < 0) {
        alert('発注数量は正の値を入力してください');
        e.target.value = 1;
        return;
      }

      if (quantity === 0) {
        alert('発注数量は1以上で入力してください');
        e.target.value = 1;
        return;
      }

      const item = orderItems.find(item => item.id === itemId);
      if (item) {
        item.数量 = quantity;
        updateTotalAmount();
        // 小計の更新
        const row = e.target.closest('tr');
        const subtotalCell = row.querySelector('td:nth-child(5)');
        subtotalCell.textContent = `¥${(item.単価 * quantity).toLocaleString()}`;
      }
    }
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', async () => {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    // バリデーション
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return;
    }

    if (!deliveryDate) {
      alert('納期を指定してください');
      return;
    }

    if (new Date(deliveryDate) < new Date(orderDate)) {
      alert('納期は発注日以降の日付を指定してください');
      return;
    }

    if (orderItems.length === 0) {
      alert('発注商品を選択してください');
      return;
    }

    // 発注データの保存
    try {
      for (const item of orderItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.id,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: item.数量,
          発注単価: item.単価,
          発注金額: item.単価 * item.数量,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(9, orderData);
      }

      alert('発注書が正常に作成されました');

      // フォームのリセット
      orderItems = [];
      renderOrderList();
      container.querySelector('#store-select').value = '';
      container.querySelector('#order-date').value = '';
      container.querySelector('#delivery-date').value = '';

      // 発注管理画面に遷移
      window.showScreen('scr-1778591852463');

    } catch (error) {
      console.error('発注書作成エラー:', error);
      alert('発注書の作成に失敗しました');
    }
  });

  // 全クリア
  container.querySelector('#btn-clear-all').addEventListener('click', () => {
    if (confirm('発注商品をすべてクリアしますか？')) {
      orderItems = [];
      renderOrderList();
    }
  });

  // 在庫状況確認
  container.querySelector('#btn-stock-check').addEventListener('click', () => {
    showStockDetails();
  });

  // 過去実績参照
  container.querySelector('#btn-history-check').addEventListener('click', () => {
    showHistoryDetails();
  });

  // 予測根拠詳細表示
  function showPredictionDetails(productId) {
    const product = allProducts.find(p => p.id === productId);
    const prediction = demandPredictions.find(p => p.商品ID === productId);

    const modal = container.querySelector('#prediction-modal');
    const details = container.querySelector('#prediction-details');

    details.innerHTML = `
      <div style="margin-bottom: 1rem;">
        <h4>${product?.商品名 || '商品名不明'}</h4>
        <p><strong>商品コード:</strong> ${product?.商品コード || 'N/A'}</p>
      </div>
      <div style="margin-bottom: 1rem;">
        <h5>予測結果</h5>
        <p><strong>予測数量:</strong> ${prediction?.予測数量 || 0}個</p>
        <p><strong>予測精度:</strong> ${prediction?.予測精度 || 0}%</p>
        <p><strong>推奨発注数量:</strong> ${prediction?.推奨発注数量 || 0}個</p>
      </div>
      <div style="margin-bottom: 1rem;">
        <h5>予測根拠</h5>
        <p><strong>モデルバージョン:</strong> ${prediction?.予測モデルバージョン || 'N/A'}</p>
        <p><strong>予測ステータス:</strong> ${prediction?.予測ステータス || 'N/A'}</p>
        <p class="muted">過去の売上データ、季節要因、天候データなどを総合的に分析して算出されています。</p>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 在庫状況詳細表示
  function showStockDetails() {
    const modal = container.querySelector('#stock-modal');
    const details = container.querySelector('#stock-details');

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>現在庫数</th>
              <th>安全在庫数</th>
              <th>リードタイム</th>
              <th>状態</th>
            </tr>
          </thead>
          <tbody>
            ${allProducts.slice(0, 10).map(product => `
              <tr>
                <td>${product.商品名}</td>
                <td>${Math.floor(Math.random() * 100)}</td>
                <td>${product.最小発注数量 || 10}</td>
                <td>${product.リードタイム日数 || 3}日</td>
                <td><span style="color: var(--primary);">正常</span></td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 過去実績詳細表示
  function showHistoryDetails() {
    const modal = container.querySelector('#history-modal');
    const details = container.querySelector('#history-details');

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>先月売上</th>
              <th>2ヶ月前売上</th>
              <th>3ヶ月前売上</th>
              <th>平均売上</th>
            </tr>
          </thead>
          <tbody>
            ${allProducts.slice(0, 10).map(product => {
              const avg = Math.floor(Math.random() * 50) + 10;
              return `
                <tr>
                  <td>${product.商品名}</td>
                  <td>${avg + Math.floor(Math.random() * 20) - 10}</td>
                  <td>${avg + Math.floor(Math.random() * 20) - 10}</td>
                  <td>${avg + Math.floor(Math.random() * 20) - 10}</td>
                  <td><strong>${avg}</strong></td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // モーダルを閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-stock-modal').addEventListener('click', () => {
    container.querySelector('#stock-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-history-modal').addEventListener('click', () => {
    container.querySelector('#history-modal').classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  container.addEventListener('click', (e) => {
    if (e.target.id === 'prediction-modal') {
      container.querySelector('#prediction-modal').classList.add('hidden');
    }
    if (e.target.id === 'stock-modal') {
      container.querySelector('#stock-modal').classList.add('hidden');
    }
    if (e.target.id === 'history-modal') {
      container.querySelector('#history-modal').classList.add('hidden');
    }
  });

  // 初期化
  loadInitialData();

  // 今日の日付を発注日にセット
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 明日の日付を納期にセット
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  container.querySelector('#delivery-date').value = tomorrow.toISOString().split('T')[0];
}
